def sha(raw):return hashlib.sha256(raw).hexdigest()
def git(*args):
    return subprocess.check_output(['git','--no-replace-objects',*args],timeout=20,env={**os.environ,'GIT_OPTIONAL_LOCKS':'0','GIT_CONFIG_NOSYSTEM':'1','GIT_CONFIG_GLOBAL':os.devnull})
def check_scope(changed,names):
    if set(changed)!=NEW_ROLES or not NEW_ROLES<=set(names) or {r for r in names if r.startswith(NEW)}!=NEW_ROLES-{WORKFLOW}:
        raise ValueError('closed new post-PF namespace differs')
def check_held(role,raw):
    if role not in HELD_HASHES or sha(raw)!=HELD_HASHES[role]:raise ValueError('held role hash differs')
def imports(role,raw,names):
    text=raw.decode('utf8')
    token=re.compile(r"(?P<comment>//[^\n]*|/\*[\s\S]*?\*/)|(?P<string>'(?:\\.|[^'\\])*'|\"(?:\\.|[^\"\\])*\")|(?P<template>`(?:\\.|[^`\\])*`)|(?P<word>[A-Za-z_$][A-Za-z0-9_$]*)|(?P<other>[^\s])")
    tokens=[];offset=0
    regex_start={'=','(','[',',',':','return','!','&','|','?',';','{','=>'}
    while offset<len(text):
        match=token.search(text,offset)
        if match is None:break
        kind,value=match.lastgroup,match.group();offset=match.end()
        if kind=='comment':continue
        if value=='/' and (not tokens or tokens[-1][1] in regex_start):
            # Regex bodies are lexical data, including character classes and
            # escaped delimiters; module words inside them are not declarations.
            cursor=offset;in_class=False;escaped=False
            while cursor<len(text):
                char=text[cursor]
                if char in '\r\n':raise ValueError('unclosed regex literal '+repr(text[max(0,match.start()-40):cursor+20]))
                if escaped:escaped=False
                elif char=='\\':escaped=True
                elif char=='[':in_class=True
                elif char==']':in_class=False
                elif char=='/' and not in_class:break
                cursor+=1
            if cursor==len(text):raise ValueError('unclosed regex literal '+repr(text[max(0,match.start()-40):cursor+20]))
            cursor+=1
            while cursor<len(text) and text[cursor].isalpha():cursor+=1
            tokens.append(('regex',text[match.start():cursor]));offset=cursor;continue
        tokens.append((kind,value))
    found=set()
    for i,(kind,value) in enumerate(tokens):
        if kind=='template' and re.search(r'\b(?:import|require)(?:\s|/\*[\s\S]*?\*/)*\(',value):raise ValueError('template dynamic import refused')
        if kind!='word' or value not in ['import','export','require']:continue
        if i and tokens[i-1][1] in ['.','#']:continue
        following=tokens[i+1:]
        if not following:raise ValueError('unsupported module declaration')
        if value=='import' and following[0][1]=='.':continue
        if value=='require' and following[0][1]!='(':continue
        if value=='require' and following[0][1]=='(':
            nesting=0
            for j,(_,item) in enumerate(following):
                nesting+=int(item=='(')-int(item==')')
                if nesting==0:
                    if j+1<len(following) and following[j+1][1]=='{':break
                    raise ValueError('dynamic require refused')
            else:raise ValueError('unparsed require declaration')
            continue
        if following[0][1]=='(':
            raise ValueError('dynamic import/require refused')
        spec=None
        if value=='import' and following[0][0]=='string':spec=following[0][1]
        elif value in ['import','export']:
            if value=='export' and following[0][1] not in ['{','*']:continue
            for j,(category,item) in enumerate(following[:1024]):
                if item==';' or (category=='word' and item in ['import','export']):break
                if category=='word' and item=='from':
                    if j+1>=len(following) or following[j+1][0]!='string':raise ValueError('module specifier shape')
                    spec=following[j+1][1];break
